// Fan the pending clients out into items.
//
// The endpoint has already filtered out anyone who received this period's
// report, so an empty list is the correct outcome of a re-run — not a fault.
const response = $input.first().json;
if (!response.ok) {
  throw new Error(`Portal refused the report list: ${response.error || 'unknown error'}`);
}

const clients = response.clients || [];
console.log(
  `${response.period} report for ${response.from} → ${response.to}: ` +
  `${clients.length} of ${response.total} client(s) still to send.`
);

if (!clients.length) {
  return [{ json: { nothing_to_send: true, period: response.period, from: response.from, to: response.to } }];
}

return clients.map((c) => ({
  json: { ...c, period: response.period, from: response.from, to: response.to, nothing_to_send: false },
}));

// Keep a per-client outcome so the execution log answers 'did Acme get their
// report?' without opening the database.
//
// A skip is not a failure: 'no_email', 'no_data' and 'already_sent' are all
// legitimate reasons not to send, and each one is worth seeing by name.
const response = $json;
const client = $('One report at a time').item.json;
const result = (response.results && response.results[0]) || {};

const outcome = result.sent
  ? 'sent'
  : result.skipped
    ? `skipped (${result.skipped})`
    : result.error
      ? `failed: ${result.error}`
      : response.ok === false
        ? `failed: ${response.error || 'portal refused the request'}`
        : 'unknown';

console.log(`${client.client_name || client.client_id}: ${outcome}`);

return [{
  json: {
    client_id: client.client_id,
    client_name: client.client_name,
    period: client.period,
    outcome,
    sent: Boolean(result.sent),
  },
}];
